<?php
namespace App\Http\Controllers\Procurement;use App\Http\Controllers\Controller;use App\Models\{GoodsReceivedNote,InventoryBatch,PurchaseOrder,PurchaseRequisition,StockTransfer,Supplier,SupplierInvoice};
class ProcurementDashboardController extends Controller{public function __invoke(){ $p=auth()->user()->property_id;return view('procurement.dashboard',['stats'=>['suppliers'=>Supplier::where('property_id',$p)->count(),'pending_requisitions'=>PurchaseRequisition::where('property_id',$p)->whereIn('status',['submitted','approved'])->count(),'open_orders'=>PurchaseOrder::where('property_id',$p)->whereNotIn('status',['received','cancelled'])->count(),'unpaid_invoices'=>SupplierInvoice::where('property_id',$p)->whereIn('status',['unpaid','part_paid'])->sum('total_amount')-SupplierInvoice::where('property_id',$p)->whereIn('status',['unpaid','part_paid'])->sum('paid_amount'),'pending_grns'=>GoodsReceivedNote::where('property_id',$p)->where('status','draft')->count(),'transfers'=>StockTransfer::where('property_id',$p)->whereNotIn('status',['received','cancelled'])->count(),'expiring'=>InventoryBatch::where('property_id',$p)->whereNotNull('expires_at')->whereBetween('expires_at',[now()->toDateString(),now()->addDays(30)->toDateString()])->count()]]);}}